package ai.elizaresearch.alphaphone; import java.util.*;import org.json.*;import android.content.Context;class AlphaCredentialStore {static Map<String,String> slots=new HashMap<>();static String owner="owner",epoch="epoch",provider="elizacloud";interface CloudChangeObserver{void changed()throws Exception;}static CloudChangeObserver observer;AlphaCredentialStore(Context c){}static void observeCloudChanges(CloudChangeObserver o){observer=o;}String readCredentialSlot(String k){return slots.get(k);}void writeCredentialSlot(String k,String v){slots.put(k,v);}void removeCredentialSlot(String k){slots.remove(k);}JSONObject providerAdmissionSnapshot()throws Exception{return new JSONObject().put("provider",provider).put("accountRef",new JSONArray(Arrays.asList("cloud","production",owner,"org")).toString()).put("sessionGeneration",epoch);}}
